// UploadPlugin 上传插件包
// @router /plugin/upload [POST]
func UploadPlugin(ctx context.Context, c *app.RequestContext) {
	token := c.PostForm("token")
	if token != config.AppConfig.Upload.Key {
		pack.RespLegacyError(c, consts.StatusUnauthorized, "没认证捏~")
		return
	}

	fileHeader, err := c.FormFile("file")
	if err != nil {
		pack.RespLegacyError(c, consts.StatusUnprocessableEntity, "缺少插件包文件")
		return
	}

	file, err := fileHeader.Open()
	if err != nil {
		pack.RespLegacyError(c, consts.StatusInternalServerError, "读取插件包失败")
		return
	}
	defer file.Close()

	content, err := io.ReadAll(file)
	if err != nil {
		pack.RespLegacyError(c, consts.StatusInternalServerError, "读取插件包失败")
		return
	}

	hlog.CtxInfof(ctx, "收到插件包: %s, 大小: %d bytes", fileHeader.Filename, len(content))

	// 与老API行为一致: 处理失败只记录日志, 仍返回成功消息
	if err := service.NewLegacyService(ctx).Upload(content); err != nil {
		hlog.CtxErrorf(ctx, "插件包更新失败: %+v", err)
	} else {
		hlog.CtxInfof(ctx, "插件包更新成功~")
	}

	c.JSON(consts.StatusOK, &legacy.UploadPluginResp{Message: "插件包更新成功~"})
}

