// GetAllPlugins 下载所有插件
// @router /plugin/get_all_plugins [GET]
func GetAllPlugins(ctx context.Context, c *app.RequestContext) {
	if _, err := os.Stat(constants.PluginsZipFile); err != nil {
		pack.RespLegacyError(c, consts.StatusNotFound, "插件包当前未上传,无法下载~")
		return
	}
	if manifest.Syncing() {
		pack.RespLegacyError(c, consts.StatusForbidden, "API正在同步插件中,请稍后重试~")
		return
	}

	if err := pack.RespZipFile(c, constants.PluginsZipFile, "Plugins.zip"); err != nil {
		pack.RespLegacyError(c, consts.StatusInternalServerError, "读取插件包失败")
	}
}

// GetPluginZip 下载单个插件(最新版本)
// @router /plugin/get_plugin_zip [GET]
func GetPluginZip(ctx context.Context, c *app.RequestContext) {
	assemblyName := c.Query("assembly_name")
	svc := service.NewLegacyService(ctx)

	filePath, ok := svc.ResolveLegacyZip(assemblyName)
	if !ok {
		pack.RespLegacyError(c, consts.StatusNotFound, "没有找到指定插件~")
		return
	}
	if manifest.Syncing() {
		pack.RespLegacyError(c, consts.StatusForbidden, "API正在同步插件中,请稍后重试~")
		return
	}

	svc.IncDownloadCount(assemblyName)

	if err := pack.RespZipFile(c, filePath, fmt.Sprintf("%s.zip", assemblyName)); err != nil {
		pack.RespLegacyError(c, consts.StatusInternalServerError, "读取插件失败")
	}
}
